script:
// Sacral section: skin, fat, muscle, bone. The ulcer crater deepens layer by layer.
const S = 196, SKB = 232, FATB = 302, MUSB = 380, BOT = 502, CX = 290;
const RED = "#c0392b", RAW = "#c9475a", TEAL = "#2a9d8f";
const RX = 566, RW = 14;                        // depth ruler
let el = {};
function txt(api, parent, s, attrs) {
  const t = api.el("text", Object.assign({"font-family": "system-ui,sans-serif", "font-weight": 700, "font-size": 18}, attrs), parent);
  t.textContent = s; return t;
}
function crater(D) {
  const h = D - S, wt = 46 + 0.56 * h, wb = 16 + 0.26 * h;
  const c = "M " + (CX - wt) + " " + S + " C " + (CX - wt + 6) + " " + (S + h * 0.55) + " " + (CX - wb - 14) + " " + D + " " + (CX - wb) + " " + D;
  const cR = " L " + (CX + wb) + " " + D + " C " + (CX + wb + 14) + " " + D + " " + (CX + wt - 6) + " " + (S + h * 0.55) + " " + (CX + wt) + " " + S;
  return {fill: c + cR + " Z", wb: wb};
}
function setup(api) {
  const r = api.random(3), lob = api.$("#lob"), fib = api.$("#fib"), trab = api.$("#trab");
  for (let i = 0; i < 24; i++) api.el("circle", {cx: 60 + r() * 480, cy: 246 + r() * 46, r: 8 + r() * 6}, lob);
  for (let y = 312; y < 378; y += 10) api.el("path", {d: "M 48 " + y + " C 200 " + (y - 4) + " 360 " + (y + 4) + " 548 " + y, fill: "none"}, fib);
  for (let i = 0; i < 30; i++) {
    const x = 60 + r() * 480, y = 404 + r() * 90;
    api.el("ellipse", {cx: x, cy: y, rx: 10 + r() * 10, ry: 5 + r() * 5}, trab);
  }
  const sec = api.$("#sec"), top = api.$("#top");
  el.hole = api.el("path", {fill: "#ffffff"}, sec);
  el.wall = api.el("path", {fill: "none", stroke: RAW, "stroke-width": 6, "stroke-linejoin": "round", "stroke-linecap": "round"}, sec);
  el.boneBase = api.el("line", {stroke: "#fffaf0", "stroke-width": 7, "stroke-linecap": "round"}, sec);
  el.boneGlow = api.el("ellipse", {fill: "none", stroke: "#ffd166", "stroke-width": 4, filter: "url(#kit-glow)"}, sec);
  // layer labels
  const lab = {stroke: "#ffffff", "stroke-width": 5, "stroke-linejoin": "round", "paint-order": "stroke", fill: "@ink"};
  [["Skin", 214], ["Fat", 268], ["Muscle", 342], ["Bone", 446]].forEach(a => txt(api, top, a[0], Object.assign({x: 66, y: a[1] + 6}, lab)));
  // depth ruler
  api.el("rect", {x: RX - RW / 2, y: S, width: RW, height: BOT - 22 - S, rx: 7, fill: "#eef3f3", stroke: "@line", "stroke-width": 1.5}, top);
  el.rFill = api.el("rect", {x: RX - RW / 2, y: S, width: RW, rx: 7, fill: RED}, top);
  [SKB, FATB, MUSB].forEach(y => api.el("line", {x1: 548, y1: y, x2: RX - RW / 2 - 2, y2: y, stroke: "@muted", "stroke-width": 2}, top));
  el.mark = api.el("path", {fill: RED, stroke: "#ffffff", "stroke-width": 2}, top);
  el.boneTxt = txt(api, top, "Bone exposed", {x: CX, y: 420, "text-anchor": "middle", fill: RED, stroke: "#ffffff", "stroke-width": 5, "stroke-linejoin": "round", "paint-order": "stroke"});
  el.stage = api.el("g", {}, top);
  api.el("rect", {x: 442, y: 440, width: 116, height: 40, rx: 20, fill: RED, filter: "url(#chipShadow)"}, el.stage);
  txt(api, el.stage, "Stage 4", {x: 500, y: 461, "text-anchor": "middle", "dominant-baseline": "central", fill: "#ffffff", "font-size": 20, "font-weight": 800});
}
function vis(api, node, k) { api.set(node, {opacity: k, display: k > 0.001 ? "inline" : "none"}); }
function render(t, api) {
  const k1 = api.seg(t, 150, 1700, "ease_in_out"), k2 = api.seg(t, 2400, 4300, "ease_in_out"), k3 = api.seg(t, 4650, 5150, "ease_out");
  const D = S + 4 + (SKB + 6 - S - 4) * k1 + (MUSB - SKB - 6) * k2 + 8 * k3;
  const c = crater(D);
  api.set(el.hole, {d: c.fill});
  api.set(el.wall, {d: c.fill.replace(" Z", "")});
  const exposed = k3 > 0;
  api.set(el.boneBase, {x1: CX - c.wb + 4, y1: D, x2: CX + c.wb - 4, y2: D});
  vis(api, el.boneBase, k3);
  api.set(el.boneGlow, {cx: CX, cy: D, rx: c.wb + 10, ry: 10});
  vis(api, el.boneGlow, api.seg(t, 4800, 5200) * (0.75 + 0.25 * Math.sin(t / 160)));
  vis(api, el.boneTxt, api.seg(t, 5000, 5350));
  // ruler follows the depth
  api.set(el.rFill, {height: Math.max(0, D - S)});
  vis(api, el.rFill, D - S > 1 ? 1 : 0);
  api.set(el.mark, {d: "M " + (RX + 9) + " " + D + " l 14 -9 l 0 18 Z"});
  const sk = api.seg(t, 5100, 5500, "back_out");
  vis(api, el.stage, api.seg(t, 5100, 5300));
  api.set(el.stage, {transform: "translate(500 460) scale(" + (0.8 + 0.2 * sk).toFixed(3) + ") translate(-500 -460)"});
}
